import torch
from torch.utils.cpp_extension import load_inline

from task import input_t, output_t


_CPP_SOURCE = r"""
torch::Tensor panel_cholesky_128(torch::Tensor input);
"""


_CUDA_SOURCE = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <c10/cuda/CUDAException.h>
#include <cuda.h>
#include <cuda_runtime.h>

__device__ __forceinline__ float row_team_sum(float value) {
    const unsigned mask = __activemask();
    value += __shfl_down_sync(mask, value, 2, 4);
    value += __shfl_down_sync(mask, value, 1, 4);
    return value;
}

__global__ void panel_cholesky_128_kernel(
    const float* __restrict__ input,
    float* __restrict__ output) {
    constexpr int N = 128;
    constexpr int ROW_THREADS = 4;
    extern __shared__ float factor[];
    const int worker = threadIdx.x;
    const int row = worker / ROW_THREADS;
    const int part = worker % ROW_THREADS;
    const int matrix = blockIdx.x;
    const float* source = input + static_cast<size_t>(matrix) * N * N;
    float* result = output + static_cast<size_t>(matrix) * N * N;

    for (int index = worker; index < N * N; index += blockDim.x) {
        const int source_row = index / N;
        const int column = index - source_row * N;
        if (column <= source_row) {
            factor[source_row * (source_row + 1) / 2 + column] = source[index];
        }
    }
    __syncthreads();

    if (row == 0 && part == 0) {
        factor[0] = sqrtf(fmaxf(factor[0], 1.0e-20f));
    }
    __syncthreads();
    for (int column = 0; column < N; ++column) {
        if (row > column) {
            const int row_base = row * (row + 1) / 2;
            const int column_base = column * (column + 1) / 2;
            float product_sum = 0.0f;
            for (int k = part; k < column; k += ROW_THREADS) {
                product_sum = fmaf(
                    factor[row_base + k], factor[column_base + k], product_sum);
            }
            product_sum = row_team_sum(product_sum);
            float solved = 0.0f;
            if (part == 0) {
                solved = (factor[row_base + column] - product_sum) /
                    factor[column_base + column];
                factor[row_base + column] = solved;
            }
            solved = __shfl_sync(__activemask(), solved, 0, ROW_THREADS);

            if (row == column + 1) {
                float square_sum = part == 0 ? solved * solved : 0.0f;
                for (int k = part; k < column; k += ROW_THREADS) {
                    const float value = factor[row_base + k];
                    square_sum = fmaf(value, value, square_sum);
                }
                square_sum = row_team_sum(square_sum);
                if (part == 0) {
                    factor[row_base + row] = sqrtf(fmaxf(
                        factor[row_base + row] - square_sum, 1.0e-20f));
                }
            }
        }
        if (column + 1 < N) {
            __syncthreads();
        }
    }

    for (int index = worker; index < N * N; index += blockDim.x) {
        const int result_row = index / N;
        const int column = index - result_row * N;
        result[index] = column <= result_row
            ? factor[result_row * (result_row + 1) / 2 + column]
            : 0.0f;
    }
}

torch::Tensor panel_cholesky_128(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "input must be CUDA");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32, "input must be float32");
    TORCH_CHECK(input.is_contiguous(), "input must be contiguous");
    TORCH_CHECK(input.dim() == 3 && input.size(1) == 128 && input.size(2) == 128,
                "input must contain 128x128 matrices");
    c10::cuda::CUDAGuard device_guard(input.device());
    torch::Tensor output = torch::empty_like(input);
    constexpr int shared_bytes = 128 * 129 / 2 * sizeof(float);
    panel_cholesky_128_kernel<<<input.size(0), 512, shared_bytes>>>(
        input.data_ptr<float>(), output.data_ptr<float>());
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}
"""


_panel_extension = load_inline(
    name="cholesky_blocked_panel128_v1",
    cpp_sources=_CPP_SOURCE,
    cuda_sources=_CUDA_SOURCE,
    functions=["panel_cholesky_128"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3", "-std=c++20"],
    with_cuda=True,
    verbose=False,
)


def _blocked_cholesky(data: torch.Tensor, block_size: int) -> torch.Tensor:
    """Left-looking blocked Cholesky, batched over all input matrices."""
    result = torch.zeros_like(data)
    n = data.shape[-1]

    for panel_start in range(0, n, block_size):
        panel_end = min(panel_start + block_size, n)
        panel = data[:, panel_start:, panel_start:panel_end].clone()
        if panel_start:
            panel_history = result[:, panel_start:, :panel_start]
            factor_history = result[
                :, panel_start:panel_end, :panel_start
            ]
            torch.baddbmm(
                panel,
                panel_history,
                factor_history.transpose(-1, -2),
                beta=1.0,
                alpha=-1.0,
                out=panel,
            )
        diagonal = panel[:, : panel_end - panel_start, :]
        factor = _panel_extension.panel_cholesky_128(diagonal.contiguous())
        result[:, panel_start:panel_end, panel_start:panel_end].copy_(factor)

        if panel_end == n:
            continue

        column = panel[:, panel_end - panel_start :, :]
        solved = torch.linalg.solve_triangular(
            factor,
            column.transpose(-1, -2),
            upper=False,
            left=True,
        ).transpose(-1, -2)
        result[:, panel_end:, panel_start:panel_end].copy_(solved)

    return result


def custom_kernel(data: input_t) -> output_t:
    batch = data.shape[0]
    n = data.shape[-1]
    if n == 1024 and batch >= 16:
        return _blocked_cholesky(data, 128)
    return torch.linalg.cholesky_ex(data, check_errors=False).L

